use super::*;
use crate::pet_runtime::{project_goal_observation as observed,store::Store};
struct F{project:ProjectFixture,store:Store,goal:Record,now:u64}
impl F{
 fn new()->Self{let mut project=ProjectFixture::new();project.bind();let now=crate::assistant_memory::now();let store=Store::ensure_native(&project.files.root.join("goals")).unwrap();let g=store.create(project.goal.spec.clone(),now).unwrap().record;let goal=store.mutate(&g.id,"ai_ollama",&g.revision,"project-binding".into(),Action::BindContext{binding:project.goal.execution_context.clone().unwrap()},now+1).unwrap().record;Self{project,store,goal,now:now+2}}
 fn scope(&self)->observed::Selection{observed::Selection::capture(&self.project.files.catalog(),"ai_ollama",&self.project.project.conversation_ids[0],&self.project.choice(),vec![observed::Reference::of(&self.goal).unwrap()],true,self.now).unwrap()}
 fn capture(&self,scope:&observed::Selection,now:u64)->Result<observed::Snapshot>{observed::capture(&self.store,&self.project.files.root.join("authority"),&self.project.files.catalog(),scope,None,now)}
}
#[test]fn selected_project_observation_is_native_as_of_data_and_normal_goal_progress_is_not_new_consent(){
 let mut f=F::new();let scope=f.scope();let before=fs::read(f.project.files.catalog()).unwrap();let goal_before=fs::read(f.project.files.root.join("goals").join(format!("{}.json",f.goal.id))).unwrap();let snapshot=f.capture(&scope,f.now).unwrap();assert!(snapshot.valid_for("ai_ollama",None));let observation=&snapshot.observations[0];assert_eq!(observation.state,crate::pet_runtime::model::State::Draft);assert!(!observation.criteria_verified&&!observation.goal_complete);assert_eq!(observation.criteria,f.goal.spec.criteria);assert_eq!(observation.response,observed::Reply::NotAdmitted);assert_eq!(observation.cumulative_charge.as_ref().unwrap().model_calls,0);assert_eq!(fs::read(f.project.files.catalog()).unwrap(),before);assert_eq!(fs::read(f.project.files.root.join("goals").join(format!("{}.json",f.goal.id))).unwrap(),goal_before);assert!(f.goal.admissions.is_empty());
 f.goal=f.store.mutate(&f.goal.id,"ai_ollama",&f.goal.revision,"own-later-pause".into(),Action::Pause,f.now+1).unwrap().record;
 assert!(scope.verify_pins(&f.store,&f.project.files.catalog(),"ai_ollama",f.now+2).is_ok());let after=f.capture(&scope,f.now+2).unwrap();assert_eq!(after.observations[0].state,crate::pet_runtime::model::State::Paused);assert_ne!(after.observations[0].goal_revision,observation.goal_revision);assert_ne!(after.observations[0].goal_hash,observation.goal_hash);assert_eq!(snapshot.observations[0].state,crate::pet_runtime::model::State::Draft,"preserved snapshot never silently becomes current");assert!(snapshot.valid_for("ai_ollama",None));assert!(!after.observations[0].criteria_verified&&!after.observations[0].goal_complete);assert!(f.goal.admissions.is_empty());
}
#[test]fn project_goal_observation_refuses_self_foreign_or_unassociated_goals_and_wrong_definition(){
 let f=F::new();let scope=f.scope();assert!(observed::capture(&f.store,&f.project.files.root.join("authority"),&f.project.files.catalog(),&scope,Some(&f.goal.id),f.now).is_err());
 let mut wrong=scope.clone();wrong.goals[0].spec_hash="d".repeat(64);assert!(f.capture(&wrong,f.now).is_err());wrong=scope.clone();wrong.project.pet_id="agent_codex".into();assert!(f.capture(&wrong,f.now).is_err());
 let mut no_project=f.goal.spec.clone();no_project.request_id="same-conversation-is-not-membership".into();let other=f.store.create(no_project,f.now).unwrap().record;wrong=scope.clone();wrong.goals=vec![observed::Reference::of(&other).unwrap()];assert!(f.capture(&wrong,f.now).is_err());
 let mut duplicate=scope.clone();duplicate.goals.push(duplicate.goals[0].clone());assert!(!duplicate.valid("ai_ollama"));let mut many=scope.clone();many.goals=(0..9).map(|i|observed::Reference{goal_id:format!("g-{:064x}",i),spec_hash:"a".repeat(64)}).collect();assert!(!many.valid("ai_ollama"));
}
#[test]fn own_project_metadata_capture_needs_no_artificial_notes_and_cannot_revive_after_identity_change(){
 let mut f=F::new();let source=f.project.project.conversation_ids[0].clone();let capture=crate::pet_memory::projects::Capture::at(&f.project.files.catalog(),"ai_ollama",&source,&f.project.choice(),f.now).unwrap();assert_eq!(capture.project(),&f.project.project);let original=fs::read(f.project.files.catalog()).unwrap();f.project.project.name="Tampered at the same revision".into();f.project.write();assert!(capture.verify(f.now+1).is_err());fs::write(f.project.files.catalog(),original).unwrap();assert!(capture.verify(f.now+2).is_err());let fresh=crate::pet_memory::projects::Capture::at(&f.project.files.catalog(),"ai_ollama",&source,&f.project.choice(),f.now+3).unwrap();assert!(fresh.verify(f.now+3).is_ok());assert!(f.goal.admissions.is_empty());
}
#[test]fn project_observation_preserves_uncertainty_and_refuses_oversized_or_tampered_payloads(){
 let f=F::new();let scope=f.scope();let snapshot=f.capture(&scope,f.now).unwrap();let mut changed=snapshot.clone();changed.observations[0].goal_complete=true;assert!(!changed.valid_for("ai_ollama",None));changed=snapshot.clone();changed.observations[0].reference.spec_hash="a".repeat(64);assert!(!changed.valid_for("ai_ollama",None));changed=snapshot.clone();changed.observations[0].intent="x".repeat(65536);changed.observations[0].criteria=vec!["c".repeat(4096);32];assert!(!changed.valid_for("ai_ollama",None),"data must fail bounded capture, never truncate");
 changed=snapshot.clone();changed.observations[0].accounting_complete=false;changed.observations[0].cumulative_charge=None;changed.observations[0].outcomes_complete=false;changed.observations[0].authenticated_subtotal.unknown_model_results=1;changed.observations[0].authenticated_subtotal.model_calls=1;assert!(changed.valid_for("ai_ollama",None));let encoded=serde_json::to_value(&changed).unwrap();assert!(encoded["observations"][0]["cumulativeCharge"].is_null());assert_eq!(encoded["observations"][0]["authenticatedSubtotal"]["unknownModelResults"],1);
}

#[test]fn selected_project_responses_keep_signed_available_unknown_and_original_data_revocation(){
 use crate::pet_runtime::{admission::{Review,Payment},authority::Authority,lease_controller::{Controller,Validity},leases::DrainOutcome};
 for known in [true,false]{
  let mut f=F::new();let authority_root=f.project.files.root.join("authority");let authority=Authority::ensure(&authority_root).unwrap();let at=crate::assistant_memory::now;
  f.goal=f.store.mutate(&f.goal.id,"ai_ollama",&f.goal.revision,"response-task".into(),Action::ProposeTask{description:"Own selected source response".into()},at()).unwrap().record;
  f.goal=f.store.mutate(&f.goal.id,"ai_ollama",&f.goal.revision,"response-plan".into(),Action::ProposePlan{task_id:f.goal.tasks[0].id.clone(),steps:vec![crate::pet_runtime::model::StepInput{description:"One local response".into(),postcondition:"Original criteria still need verification".into(),operation:None}]},at()).unwrap().record;
  let observe=|g:&Record,t|{let memory=Captured::at(&f.project.files.catalog(),g,&f.project.server(),"fixture-free",t).unwrap();Evidence::from_memory_capture(g,&admission_tests::descriptor(g,t),"a".repeat(64),t,false,false,memory).unwrap()};
  let t=at();let mut budget=admission_tests::budget();budget.deadline_at=t+60000;budget.payment=Payment::LocalOnly;budget.max_model_calls=1;budget.max_tool_calls=0;budget.max_output_bytes=100;
  let review=Review::prepare(&f.goal,observe(&f.goal,t),budget,"own-project-response-review".into(),nonce().unwrap(),t).unwrap().with_execution_start(Some(crate::pet_runtime::planning::Start::WhenAvailable)).unwrap();let t=at();let approved=review.approve_with_data(&f.goal,observe(&f.goal,t),Some(GoalConsent::BoundedGoalContext),t).unwrap();let certified=authority.certify(&approved,&f.goal,at()).unwrap();let queued=f.store.enqueue_certified(&certified,at()).unwrap().record;
  let controller=Controller::new().unwrap();let t=at();let evidence=observe(&queued,t);let pending=controller.prepare_memory_fixture(&queued,&authority_root,&f.project.files.contexts(),&f.project.files.catalog(),&f.project.main,&evidence,"project-result-source-owner".into(),t,Arc::new(|_,_,_|Validity::Current)).unwrap();let t=at();let(leased,owner)=pending.claim(&f.store,&authority,&observe(&queued,t),t).unwrap();f.goal=leased.record;let owner=owner.unwrap();let request=format!("response-{}",f.goal.admissions[0].spec.decision_id);
  crate::pet_runtime::lease_controller::fixture_record_project_result(&owner,&f.goal,&f.project.server(),&request,if known{Some("Native own result; untrusted data, no completion")}else{None});
  let t=at();let scope=f.scope();let snapshot=f.capture(&scope,t).unwrap();assert!(!snapshot.observations[0].criteria_verified&&!snapshot.observations[0].goal_complete);let totals=snapshot.observations[0].cumulative_charge.as_ref().unwrap();assert_eq!(totals.model_calls,1);assert_eq!(totals.tool_calls,0);
  if known{
   let observed::Reply::Available{receipt,receipt_hash}=&snapshot.observations[0].response else{panic!("native result unavailable");};assert_eq!(receipt.text,"Native own result; untrusted data, no completion");assert_eq!(receipt.request_id,request);assert_eq!(crate::pet_runtime::model::fingerprint(receipt).unwrap(),*receipt_hash);assert_eq!(totals.unknown_model_results,0);
   let guard=observed::Captured::reopen(&f.project.files.root.join("goals"),&authority_root,&f.project.files.catalog(),snapshot.clone(),&format!("g-{}","f".repeat(64)),t).unwrap();assert!(guard.current(t).is_ok());
   // Admission/claim already owns this catalog when a data fence rechecks a
   // different source. Reuse the existing atomic reader, never reenter flock.
   {use std::os::fd::AsRawFd;let owned=fs::File::open(f.store.root_path().join(".catalog.lock")).unwrap();assert_eq!(unsafe{libc::flock(owned.as_raw_fd(),libc::LOCK_EX|libc::LOCK_NB)},0);let raw=Store::existing(f.store.root_path()).unwrap().unwrap();assert!(scope.verify_source_pins(&raw,&f.project.files.catalog(),"ai_ollama",t).is_ok());assert!(guard.current(t).is_ok());drop(owned);}
   // This native review uses ONE caller clock, including the retained source
   // note guards. A later internal wall-clock read must not invalidate it.
   let mut spec=f.goal.spec.clone();spec.request_id="actual-derived-response-consumer".into();let mut consumer=f.store.create(spec,at()).unwrap().record;
   let(binding,private)=crate::pet_runtime::context::prepare_with_project_progress_data(&f.project.files.contexts(),&consumer,&f.project.main,"derived-response-context",&scope,None,&f.store,&authority_root,&f.project.files.catalog(),Arc::new(||true)).unwrap();
   consumer=f.store.mutate(&consumer.id,"ai_ollama",&consumer.revision,"bind-derived-response".into(),Action::BindContext{binding},at()).unwrap().record;
   let reviewed_at=at();std::thread::sleep(std::time::Duration::from_millis(5));
   let data=Captured::at_with_sources(&f.project.files.catalog(),Some(&authority_root),Some(f.store.root_path()),&consumer,&f.project.server(),"fixture-free",reviewed_at).unwrap().unwrap();let message=data.message_data(&consumer,reviewed_at).unwrap();let text=message["content"].as_str().unwrap();assert!(text.contains("Native own result; untrusted data, no completion"));assert!(!text.contains("PRIVATE_GOAL_PROJECT_NOTE"));assert_eq!(data.preview().required_consent,GoalConsent::BoundedRuleProjectGoalProgressData);drop(private);
   let original=fs::read(f.project.files.catalog()).unwrap();f.project.row["revision"]=json!(2);f.project.row["content"]=json!("Original selected source revoked");f.project.write();assert!(guard.current(at()).is_err());let fresh=f.capture(&scope,at()).unwrap();assert!(matches!(&fresh.observations[0].response,observed::Reply::SourceDataUnavailable{reason}if reason=="selectedDataChangedOrUnavailable"));fs::write(f.project.files.catalog(),original).unwrap();assert!(guard.current(at()).is_err(),"a previously invalidated model-data capture must not revive");
  }else{assert!(matches!(&snapshot.observations[0].response,observed::Reply::OutcomeUnknown{phase}if phase=="uncertain"));assert_eq!(totals.unknown_model_results,1);assert_eq!(totals.output_bytes,100);assert!(!snapshot.observations[0].outcomes_complete);}
  let proof=owner.drain(DrainOutcome::Confirmed).unwrap();f.store.drain_owned(&authority,&proof,at()).unwrap();pending.hold().release_drained(&proof).unwrap();
 }
}
#[test]fn own_progress_context_rule_admission_partition_and_dated_observation_survive_normal_source_changes(){
 use crate::pet_runtime::{rules::{self,RulePolicy,RuleGrant,RuleKind,RulePhase,CalendarReadOutcome},authority::Authority,admission::{Review,Payment}};
 let mut f=F::new();let at=crate::assistant_memory::now;let now=at();let root=f.project.files.root.join("authority");let authority=Authority::ensure(&root).unwrap();
 let first=chrono::DateTime::from_timestamp_millis(now as i64).unwrap().format("%Y-%m-%d").to_string();let scope=f.scope();
 let definition=serde_json::from_value(json!({"name":"Follow exact own project goals","intent":"Report observed progress and criteria; suggest decisions without executing them","criteria":["Review actual result; never infer completion"],"schedule":{"kind":"daily","firstDate":first,"days":3,"localTime":"00:00","timeZone":"UTC","weekdays":[1,2,3,4,5,6,7],"overlap":"earlier","gap":"skip"},"missed":"coalesce","graceSeconds":300,"dataScope":{"projectProgress":{"sourceConversationId":scope.source_conversation_id,"project":f.project.choice(),"goals":scope.goals,"includeLatestResponse":true,"notes":[]}},"limits":{"maxOccurrences":2,"maxModelCalls":2,"maxToolCalls":0,"maxOutputBytes":8192,"occurrenceOutputBytes":4096,"occurrenceTimeoutSeconds":86400}})).unwrap();
 let rule=rules::Rule{id:format!("rule-{}","b".repeat(64)),revision:1,owner:f.goal.spec.owner.clone(),state:rules::State::Draft,created_at:now,updated_at:now,definition};
 let schedule={let _lock=crate::pet_calendar::TEST_SERIAL.lock().unwrap();crate::pet_calendar::schedule::resolve(&rule.definition.schedule,||true).unwrap()};let valid_until=schedule.slots.last().unwrap().at.unwrap()+86400000;
 let policy:RulePolicy=serde_json::from_value(json!({"schemaVersion":7,"scope":"boundedRuleRecurrenceWithProjectGoalProgress","rule":rule,"payment":"localOnly","destination":{"kind":"server","provider":"ollama","endpoint":"http://127.0.0.1:12345/api/chat","model":"fixture-free"},"model":"fixture-free","engineBinding":null,"policyRevision":"a".repeat(64),"descriptorSemantics":"b".repeat(64),"schedule":schedule,"preparedAt":now,"validUntil":valid_until,"projectProgressData":{"schemaVersion":1,"consent":"boundedRuleProjectGoalProgressData","selection":scope,"maxDataBytes":131072,"maxInputBytes":262144,"maxCaptureSeconds":10,"maxReadsPerOccurrence":1}})).unwrap();assert!(policy.valid());
 let parent=RuleGrant{schema_version:12,kind:RuleKind::RuleRecurrence,decision_id:nonce().unwrap(),revision:nonce().unwrap(),policy:policy.clone(),phase:RulePhase::Active,approved_at:now,updated_at:now,revoked_at:None,reservations:vec![],intent_retirements:vec![],succession:None,revision_authority:None};authority.issue_rule(&parent,now,||true).unwrap();let mut saved=vec![];
 for index in 0..2{
  let t=policy.schedule.slots[index].at.unwrap().max(at())+10;let owned=authority.begin_owned_rule_calendar(&parent.decision_id,&policy.hash().unwrap(),index,t,||true).unwrap();
  let mut goal=f.store.create(policy.goal_spec(index).unwrap(),t).unwrap().record;
  goal=f.store.mutate(&goal.id,"ai_ollama",&goal.revision,format!("task-{index}"),Action::ProposeTask{description:"Report only selected own progress".into()},t).unwrap().record;
  goal=f.store.mutate(&goal.id,"ai_ollama",&goal.revision,format!("plan-{index}"),Action::ProposePlan{task_id:goal.tasks[0].id.clone(),steps:vec![crate::pet_runtime::model::StepInput{description:"One finite response".into(),postcondition:"Response is data; verify criteria separately".into(),operation:None}]},t).unwrap().record;
  let(binding,writer)=crate::pet_runtime::context::prepare_with_project_progress_data(&f.project.files.contexts(),&goal,&f.project.main,&format!("capture-{index}"),&scope,None,&f.store,&root,&f.project.files.catalog(),Arc::new(||true)).unwrap();assert_eq!(binding.schema_version,12);assert!(binding.memory.is_none());assert_eq!(binding.project(),Some(&f.project.project));assert_eq!(binding.source_messages,0);assert_eq!(binding.copied_messages,0);assert!(writer.history("ollama").is_empty());
  let expected_state=if index==0{crate::pet_runtime::model::State::Draft}else{crate::pet_runtime::model::State::Paused};assert_eq!(binding.project_progress.as_ref().unwrap().observations[0].state,expected_state);
  let original_message=writer.goal_memory_message(&goal.id).unwrap().unwrap();let text=original_message["content"].as_str().unwrap();assert!(text.contains("explicitSelectedProjectGoalProgress")&&text.contains("observationsAreAsOf"));assert!(!text.contains("PRIVATE_GOAL_PROJECT_NOTE")&&!text.contains("UNSELECTED_SOURCE_DIALOGUE"));
  let t=t.max(at());
  goal=f.store.mutate(&goal.id,"ai_ollama",&goal.revision,format!("bind-{index}"),Action::BindContext{binding:binding.clone()},t).unwrap().record;
  authority.finish_rule_calendar_read(&owned,CalendarReadOutcome::Captured{goal_id:goal.id.clone(),context_hash:crate::pet_runtime::model::fingerprint(&binding).unwrap()},t+1,||true).unwrap();drop(owned);
  let actual=authority.rule_grant(&parent.decision_id).unwrap();let allocation=&actual.reservations[index];let reference=actual.reference(allocation).unwrap();assert_eq!(reference.schema_version,4);assert!(reference.progress_context(&binding));
  let capture=Captured::at_with_sources(&f.project.files.catalog(),Some(&root),Some(f.store.root_path()),&goal,&f.project.server(),"fixture-free",t+2).unwrap().unwrap();assert_eq!(capture.preview().required_consent,GoalConsent::BoundedRuleProjectGoalProgressData);assert_eq!(capture.grant().schema_version,13);assert!(capture.confirm(&goal,&f.project.server(),"fixture-free",Some(GoalConsent::BoundedGoalContext),t+2).is_err());
  let evidence=||{let c=Captured::at_with_sources(&f.project.files.catalog(),Some(&root),Some(f.store.root_path()),&goal,&f.project.server(),"fixture-free",t+2).unwrap();Evidence::from_memory_capture(&goal,&admission_tests::descriptor(&goal,t+2),policy.policy_revision.clone(),t+2,false,false,c).unwrap()};
  let budget=crate::pet_runtime::admission::Budget{deadline_at:allocation.deadline_at,max_model_calls:1,max_tool_calls:0,max_output_bytes:4096,max_tokens:None,max_cost_micros:None,payment:Payment::LocalOnly};
  assert!(Review::prepare(&goal,evidence(),budget.clone(),format!("manual-{index}"),nonce().unwrap(),t+2).unwrap().with_execution_start(Some(crate::pet_runtime::planning::Start::WhenAvailable)).is_err(),"ordinary review cannot promote progress data into a manual grant");
  assert!(evidence().rule_binding(&policy));let approved=Review::prepare_rule_occurrence(&goal,evidence(),budget,reference,None,t+2).unwrap();assert_eq!(approved.spec().schema_version,32);assert!(approved.spec().binding_format());assert!(actual.child_matches(allocation,approved.spec()));
  let mut forged=approved.spec().clone();forged.memory_data.as_mut().unwrap().consent=GoalConsent::BoundedRulePinnedProjectData;assert!(!forged.binding_format());forged=approved.spec().clone();forged.context.project_progress.as_mut().unwrap().observations[0].state=crate::pet_runtime::model::State::Cancelled;forged.context_hash=crate::pet_runtime::model::fingerprint(&forged.context).unwrap();assert!(!actual.child_matches(allocation,&forged),"the own signed read pins original as-of data, not merely its goal references");
  authority.bind_rule_admission(approved.spec(),t+2,||true).unwrap();let certified=authority.certify(&approved,&goal,t+2).unwrap();let queued=f.store.enqueue_certified(&certified,t+2).unwrap().record;assert_eq!(queued.schema_version,69);queued.validate().unwrap();authority.verify_queued(&queued,t+2).unwrap();saved.push(queued);
  if index==0{f.goal=f.store.mutate(&f.goal.id,"ai_ollama",&f.goal.revision,"source-progress-after-capture".into(),Action::Pause,at()).unwrap().record;assert_eq!(writer.goal_memory_message(&goal.id).unwrap(),Some(original_message),"source progress does not rewrite or invalidate a sealed as-of observation");}drop(writer);
 }
 let reopened=Authority::existing(&root).unwrap();let bytes=fs::read(root.join(format!("{}.json",parent.decision_id))).unwrap();assert_eq!(reopened.rule_status(&rule,true).unwrap().remaining_occurrences,Some(0));for goal in &saved{assert_eq!(serde_json::to_value(f.store.read(&goal.id,"ai_ollama").unwrap()).unwrap(),serde_json::to_value(goal).unwrap());}assert_eq!(fs::read(root.join(format!("{}.json",parent.decision_id))).unwrap(),bytes);
 let restore=crate::pet_runtime::restoration::Review::capture(&root,f.store.root_path(),&"d".repeat(64),||Ok(())).unwrap();let preview=restore.preview().unwrap();assert_eq!(preview["historicalGoals"],3);let view=preview["grants"].as_array().unwrap().iter().find(|r|r["ruleId"]==rule.id).unwrap();assert_eq!(view["signatureValid"],true);assert_eq!(view["ruleReservations"],2);let fingerprint=restore.fingerprint().unwrap();restore.apply(&fingerprint,||Ok(())).unwrap();
 let historical=Authority::existing(&root).unwrap().rule_status(&rule,true).unwrap();assert!(historical.snapshot_only);assert_eq!(historical.remaining_occurrences,None);for goal in &saved{assert_eq!(serde_json::to_value(f.store.read(&goal.id,"ai_ollama").unwrap()).unwrap(),serde_json::to_value(goal).unwrap());let snapshot=goal.execution_context.as_ref().unwrap().project_progress.as_ref().unwrap().clone();assert!(observed::Captured::reopen(f.store.root_path(),&root,&f.project.files.catalog(),snapshot,&goal.id,at()).is_err(),"restored as-of data is preserved, not current model authority");}assert_eq!(fs::read(root.join(format!("{}.json",parent.decision_id))).unwrap(),bytes);
}
